[{"id": "call_9qeow1mw", "function": {"index": 0, "name": "write_file", "arguments": {"path": "config_reader.py", "content": "def read_settings(text):
    settings = {}

    for line in text.splitlines():
        # Strip surrounding whitespace
        stripped = line.strip()

        # Skip blank lines and comment lines
        if not stripped or stripped.startswith('#'):
            continue

        # Split on first '=' only
        if '=' not in stripped:
            raise ValueError("Malformed line: missing '='")

        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()

        # Check for duplicate keys
        if key in settings:
            raise ValueError(f"Duplicate key: {key}")

        # Unknown keys are allowed (just ignore them based on requirements)
        # Required keys: endpoint and enabled
        if key == 'endpoint':
            settings['endpoint'] = value
        elif key == 'enabled':
            # Parse boolean - must be exactly "true" or "false"
            if value.lower() not in ('true', 'false'):
                raise ValueError(f"Invalid boolean value: {value}")
            settings[key] = value.lower() == 'true'

    # Check required keys
    if 'endpoint' not in settings:
        raise ValueError("Missing required key: endpoint")
    if 'enabled' not in settings:
        raise ValueError("Missing required key: enabled")

    return settings
